package dev.monthendbuddy.common.persistence;

import java.time.Instant;
import java.util.UUID;

import jakarta.persistence.Column;
import jakarta.persistence.Id;
import jakarta.persistence.MappedSuperclass;
import jakarta.persistence.Version;

import org.hibernate.annotations.CreationTimestamp;
import org.hibernate.annotations.UpdateTimestamp;
import org.hibernate.annotations.UuidGenerator;

/**
 * Identity, timestamps and optimistic locking for every entity (LLD §2). IDs are time-ordered UUIDv7 generated by
 * the application, which keeps index inserts local and lets Hibernate batch inserts (no {@code IDENTITY} columns).
 */
@MappedSuperclass
public abstract class BaseEntity {

	@Id
	@UuidGenerator(style = UuidGenerator.Style.VERSION_7)
	@Column(name = "id", nullable = false, updatable = false)
	protected UUID id;

	@CreationTimestamp
	@Column(name = "created_at", nullable = false, updatable = false)
	protected Instant createdAt;

	@UpdateTimestamp
	@Column(name = "updated_at", nullable = false)
	protected Instant updatedAt;

	@Version
	@Column(name = "version", nullable = false)
	protected long version;

	public UUID getId() {
		return id;
	}

	public Instant getCreatedAt() {
		return createdAt;
	}

	public Instant getUpdatedAt() {
		return updatedAt;
	}

	public long getVersion() {
		return version;
	}

}
